import json
from datetime import datetime, timezone

filepath = "/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-13-projects-contamcal-irt-calibration/5e373a9e-b910-4491-9557-54675d2d653c/tool-results/mcp-agent-ml-research-read_registry-1779085189350.txt"

with open(filepath, 'r') as f:
    raw = json.load(f)

registry = json.loads(raw['result'])
data = registry['data']
exps = data['experiments']

def parse_dt(s):
    if not s:
        return None
    try:
        return datetime.fromisoformat(s.replace('Z', '+00:00'))
    except:
        return None

def duration_secs(created, completed):
    if not created or not completed:
        return None
    c = parse_dt(created)
    d = parse_dt(completed)
    if not c or not d:
        return None
    delta = d - c
    total_secs = int(delta.total_seconds())
    return total_secs if total_secs > 0 else None

def fmt_secs(secs):
    if not secs:
        return ''
    secs = int(secs)
    h = secs // 3600
    m = (secs % 3600) // 60
    return f"{h}h {m}m" if h > 0 else f"{m}m"

# Print summary stats for SFT by model
print("=== SFT DURATION STATS BY MODEL (SUCCESS only) ===\n")

# Collect SFT runs by model
model_sft = {}
for exp_id, exp in exps.items():
    if exp.get('status') != 'DONE':
        continue
    if '_sft_' not in exp_id.lower() and not exp_id.lower().endswith('_sft'):
        continue
    if exp.get('conclusion') not in ('success', 'completed'):
        continue

    spec = exp.get('spec', {}) or {}
    model = spec.get('model_name') or ''
    if not model:
        # infer from ID
        for m in ['0.5B', '05B', '1.5B', '15B', '3B', 'llama32', 'Llama']:
            if m.lower() in exp_id.lower():
                model = m
                break

    wall_secs = spec.get('wall_clock_seconds')
    if wall_secs:
        dur = int(wall_secs)
    else:
        dur = duration_secs(exp.get('created_at'), exp.get('completed_at'))

    if dur and dur > 0:
        if model not in model_sft:
            model_sft[model] = []
        model_sft[model].append({'id': exp_id, 'dur': dur, 'spec': spec})

for model, runs in sorted(model_sft.items()):
    durs = [r['dur'] for r in runs]
    avg = sum(durs) / len(durs)
    min_d = min(durs)
    max_d = max(durs)
    print(f"{model or '(unknown)':<35} n={len(runs):>3}  avg={fmt_secs(avg):<10} min={fmt_secs(min_d):<10} max={fmt_secs(max_d)}")
    for r in sorted(runs, key=lambda x: x['dur']):
        spec = r['spec']
        dosage_label = ''
        for part in r['id'].split('_'):
            if part.startswith('d') and len(part) <= 5 and part[1:].isdigit():
                dosage_label = part
                break
        data_count = spec.get('data_count', '')
        lora_r = spec.get('lora_r', '') or spec.get('lora_rank', '')
        lora_alpha = spec.get('lora_alpha', '')
        lr = spec.get('lr', '') or spec.get('learning_rate', '')
        bs = spec.get('batch_size', '')
        ga = spec.get('grad_accum', '')
        print(f"  {r['id']:<50} {fmt_secs(r['dur']):<10} data_count={data_count:<8} lora_r={lora_r:<4} lora_alpha={lora_alpha:<4} lr={lr:<7} bs={bs} ga={ga}")
    print()
